-- ============================================================
-- AI 诊断造数 seed SQL（交付给 my-xhs-ai 团队，2026-08-16）
-- 用途：为 AI 归因诊断提供可对比的订单/支付/事件样本
-- 口径：
--   分片路由：库=uid%4、表=(uid/4)%4（订单域）
--   漏斗：浏览(t_counter VIEW) > 加购(t_cart_event ADD) > 下单(t_order)
--   时间：前 7 天 vs 后 7 天（升降对比，NOW() 相对偏移可重复执行）
--   状态：订单 0待付款/1已付款/2已发货/3已完成/4已取消/5已退款
--         支付 0待支付/1已支付/2失败/3已退款
-- 幂等：固定 ID 段 9000000000000xxx，重复执行前先 DELETE 同段
-- 执行账号：需对 4 个分片库 + payment/cart/content/counter 有写权限
-- ============================================================

-- ---------- 0. 幂等清理（重跑前执行） ----------
SET @U1=10001,@U2=10002,@U3=10003,@U4=10004;
DELETE FROM my_xhs_order_1.t_order_0 WHERE id BETWEEN 9000000000000000001 AND 9000000000000000099;
DELETE FROM my_xhs_order_2.t_order_0 WHERE id BETWEEN 9000000000000000001 AND 9000000000000000099;
DELETE FROM my_xhs_order_3.t_order_0 WHERE id BETWEEN 9000000000000000001 AND 9000000000000000099;
DELETE FROM my_xhs_order_0.t_order_1 WHERE id BETWEEN 9000000000000000001 AND 9000000000000000099;
DELETE FROM my_xhs_payment.t_payment WHERE id BETWEEN 9000000000000000101 AND 9000000000000000199;
DELETE FROM my_xhs_cart.t_cart_event WHERE id BETWEEN 9000000000000000201 AND 9000000000000000299;
DELETE FROM my_xhs_content.t_note_event WHERE id BETWEEN 9000000000000000301 AND 9000000000000000399;
DELETE FROM my_xhs_counter.t_counter WHERE id BETWEEN 9000000000000000401 AND 9000000000000000499;

