  DATE_SUB(NOW(),INTERVAL 5 DAY),NULL,NULL,NULL,0,DATE_SUB(NOW(),INTERVAL 6 DAY),DATE_SUB(NOW(),INTERVAL 5 DAY)),
 (9000000000000000003,10001,'AI202608140003',299.70,299.70,0.00,NULL,3,'{"receiver":"AI测试用户"}','AI seed 后7天-已完成',
  DATE_SUB(NOW(),INTERVAL 2 DAY),DATE_SUB(NOW(),INTERVAL 2 DAY),DATE_SUB(NOW(),INTERVAL 1 DAY),NULL,0,DATE_SUB(NOW(),INTERVAL 3 DAY),DATE_SUB(NOW(),INTERVAL 1 DAY));
-- 分片2 uid=10002（db2 tb0）：前7天 取消单；后7天 待付款
  NULL,NULL,NULL,DATE_SUB(NOW(),INTERVAL 10 DAY),0,DATE_SUB(NOW(),INTERVAL 11 DAY),DATE_SUB(NOW(),INTERVAL 10 DAY)),
 (9000000000000000005,10002,'AI202608150005',199.80,199.80,0.00,NULL,0,'{"receiver":"AI测试用户2"}','AI seed 后7天-待付款',
  NULL,NULL,NULL,NULL,0,DATE_SUB(NOW(),INTERVAL 1 DAY),DATE_SUB(NOW(),INTERVAL 1 DAY));
-- 分片3 uid=10003（db3 tb0）：后7天 已发货
  DATE_SUB(NOW(),INTERVAL 3 DAY),DATE_SUB(NOW(),INTERVAL 2 DAY),NULL,NULL,0,DATE_SUB(NOW(),INTERVAL 4 DAY),DATE_SUB(NOW(),INTERVAL 2 DAY));
-- 分片0 uid=10004（db0 tb1）：前7天 已支付；后7天 已完成（保证 4 分片行数均 >0）
  DATE_SUB(NOW(),INTERVAL 9 DAY),NULL,NULL,NULL,0,DATE_SUB(NOW(),INTERVAL 10 DAY),DATE_SUB(NOW(),INTERVAL 9 DAY)),
 (9000000000000000008,10004,'AI202608130008',259.70,239.70,20.00,2088880151371755521,3,'{"receiver":"AI测试用户4"}','AI seed 后7天-已完成(用券)',
  DATE_SUB(NOW(),INTERVAL 4 DAY),DATE_SUB(NOW(),INTERVAL 4 DAY),DATE_SUB(NOW(),INTERVAL 2 DAY),NULL,0,DATE_SUB(NOW(),INTERVAL 5 DAY),DATE_SUB(NOW(),INTERVAL 2 DAY));

